import test from 'node:test';
import assert from 'node:assert/strict';
import {createStore,currentProfile,switchProfile,clearProfile,loadStore,saveStore,STORE_KEY,getPractice,select,practiceAttempt} from '../dist/model.js';
import {loopBank,boundedDivision,startLoop,getLoop,loopAction,loopQuestion,loopEvidence,reviewLists,localDay,addDays,validLoopState} from '../dist/loop-model.js';
import {loopMarkup,loopParentMarkup,loopWrongsMarkup,reviewMarkup} from '../dist/loop-ui.js';
const time=new Date(2026,10,11,12);
const act=(p,r,a,v=null,at=time)=>loopAction(p,r.id,r.revision,a,v,at);
const answer=(p,r,v,at=time)=>{assert.equal(act(p,r,'select',v,at),true);assert.equal(act(p,r,'submit',null,at),true);};
function guide(p,r,at=time){for(let i=0;i<2;i++){const step=loopQuestion(r).steps[i];assert.equal(act(p,r,'next',null,at),false);assert.equal(act(p,r,'guide',step.choices[1],at),true);assert.equal(act(p,r,'guide',step.answer,at),false);assert.equal(act(p,r,'next',null,at),true);}}
const mem=()=>{const map=new Map();return {getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v)};};
for(const subject of Object.keys(loopBank))test(`${subject}: first wrong, two guided choices, original retry and distinct transfer retain separate evidence`,()=>{const p=currentProfile(createStore()),r=startLoop(p,subject,{at:time}),q=loopQuestion(r),wrong=q.choices.find(c=>c!==q.answer);answer(p,r,wrong);assert.equal(r.phase,'guide1');assert.match(loopMarkup(r),/第一次选了/);guide(p,r);answer(p,r,q.answer);assert.equal(r.phase,'transfer');assert.notEqual(loopQuestion(r).question,q.question);answer(p,r,loopQuestion(r).answer);assert.equal(r.phase,'complete');assert.deepEqual(r.answers.map(a=>[a.role,a.correct,a.assisted]),[['first',false,false],['retry',true,true],['transfer',true,false]]);assert.equal(validLoopState(p.learningLoop),true);assert.equal(loopEvidence(p)[0].wrongs.length,1);assert.match(loopParentMarkup(p),/引导后原题再试/);assert.match(loopWrongsMarkup(p),new RegExp(wrong));assert.equal(p.learningLoop.reviews[subject].due,'2026-11-14');assert.equal(act(p,r,'submit'),false);});
test('retry failure reveals original explanation but does not block transfer or count as independent',()=>{const p=currentProfile(createStore()),r=startLoop(p,'math',{at:time});act(p,r,'skip');guide(p,r);answer(p,r,'9');assert.equal(r.phase,'transfer');answer(p,r,'4');assert.equal(r.answers[1].correct,false);assert.equal(r.answers[2].correct,false);assert.equal(p.learningLoop.reviews.math.due,'2026-11-12');assert.equal(loopEvidence(p)[0].wrongs.length,3);assert.equal(validLoopState(p.learningLoop),true);});
test('first success bypasses help; transfer not revealed before submission; invalid actions and double submits do nothing',()=>{const p=currentProfile(createStore()),r=startLoop(p,'math',{at:time});assert.equal(act(p,r,'guide','x'),false);assert.equal(act(p,r,'select','1000'),false);assert.equal(act(p,r,'submit'),false);act(p,r,'select','4');const rev=r.revision;assert.equal(loopAction(p,r.id,rev,'submit',null,time),true);assert.equal(loopAction(p,r.id,rev,'submit',null,time),false);assert.equal(r.phase,'transfer');assert.equal(r.answers.length,1);assert.doesNotMatch(loopMarkup(r),/20 ÷ 4 = 5/);answer(p,r,'5');assert.match(loopMarkup(r),/20 ÷ 4 = 5/);assert.equal(r.guides.length,0);assert.equal(validLoopState(p.learningLoop),true);});
test('refresh preserves every guide and selection stage; repeated stale actions and completion never duplicate',()=>{const storage=mem();let s=createStore(),p=currentProfile(s),r=startLoop(p,'english',{at:time});answer(p,r,'an');for(let i=0;i<2;i++){act(p,r,'guide',loopQuestion(r).steps[i].answer);saveStore(storage,s);const loaded=loadStore(storage);assert.equal(loaded.warning,'');s=loaded.store;p=currentProfile(s);r=getLoop(p,'english');assert.equal(r.guides.length,i+1);assert.equal(act(p,r,'guide','a'),false);act(p,r,'next');}act(p,r,'select','a');saveStore(storage,s);s=loadStore(storage).store;p=currentProfile(s);r=getLoop(p,'english');assert.equal(r.selected,'a');act(p,r,'submit');answer(p,r,'an');saveStore(storage,s);s=loadStore(storage).store;p=currentProfile(s);r=getLoop(p,'english');assert.equal(act(p,r,'submit'),false);assert.equal(startLoop(p,'english'),r);assert.equal(p.learningLoop.runs.length,1);});
function success(p,subject='math',at=time){const r=startLoop(p,subject,{at});answer(p,r,loopQuestion(r).answer,at);answer(p,r,loopQuestion(r).answer,at);return r;}
test('local calendar scheduling: today/overdue, future, midnight, year and leap-day boundaries',()=>{assert.equal(localDay(new Date(2026,10,11,23,59,59)),'2026-11-11');assert.equal(addDays('2026-12-31',1),'2027-01-01');assert.equal(addDays('2028-02-28',1),'2028-02-29');assert.equal(addDays('2027-02-28',1),'2027-03-01');assert.throws(()=>addDays('2026-02-30',1));const p=currentProfile(createStore());success(p);assert.equal(reviewLists(p,new Date(2026,10,13,23,59,59)).future.length,1);assert.equal(reviewLists(p,new Date(2026,10,14,0,0,0)).due.length,1);assert.equal(reviewLists(p,new Date(2026,10,20)).due.length,1);assert.match(reviewMarkup(p,time),/将来到期/);});
test('early correct keeps due, early failure can bring it forward; due review independently correct schedules three days',()=>{const p=currentProfile(createStore());success(p);let r=startLoop(p,'math',{kind:'review',at:time});assert.equal(r.early,true);answer(p,r,'3');assert.equal(p.learningLoop.reviews.math.due,'2026-11-14');r=startLoop(p,'math',{kind:'review',at:time,restart:true});answer(p,r,'6');guide(p,r);answer(p,r,'3');assert.equal(p.learningLoop.reviews.math.due,'2026-11-12');assert.equal(r.answers[1].assisted,true);assert.equal(validLoopState(p.learningLoop),true);const due=new Date(2026,10,12,12);r=startLoop(p,'math',{kind:'review',at:due,restart:true});assert.equal(r.early,false);answer(p,r,'3',due);assert.equal(p.learningLoop.reviews.math.due,'2026-11-15');assert.equal(validLoopState(p.learningLoop),true);});
test('new practice cannot postpone an overdue review; unfinished review persists and remains listed',()=>{const p=currentProfile(createStore());success(p);const later=new Date(2026,10,20,12),r=startLoop(p,'math',{at:later,restart:true});answer(p,r,'4',later);answer(p,r,'5',later);assert.equal(p.learningLoop.reviews.math.due,'2026-11-14');const review=startLoop(p,'math',{kind:'review',at:later});act(p,review,'skip',null,later);assert.equal(reviewLists(p,later).due.length,1);assert.equal(startLoop(p,'math',{kind:'review',restart:true}),review);assert.equal(validLoopState(p.learningLoop),true);});
test('A/B isolation, profile clearing, old records and absent extension remain compatible',()=>{const s=createStore(),storage=mem(),old=getPractice(s,'math');select(old,'3');practiceAttempt(s,old);const original=structuredClone(s.profiles.A.wrongs);success(currentProfile(s));switchProfile(s,'B');assert.equal(getLoop(currentProfile(s),'math'),null);assert.equal(reviewLists(currentProfile(s)).due.length,0);assert.equal(loopAction(currentProfile(s),'loop-1',0,'skip'),false);success(currentProfile(s),'english');saveStore(storage,s);assert.equal(loadStore(storage).warning,'');clearProfile(s);assert.equal(s.profiles.B.learningLoop,undefined);assert.deepEqual(s.profiles.A.wrongs,original);const legacy=createStore();saveStore(storage,legacy);assert.deepEqual(loadStore(storage).store,legacy);});
test('malformed extension preserves all legacy and other-profile data with an explicit warning',()=>{const s=createStore(),storage=mem(),old=getPractice(s,'math');select(old,'3');practiceAttempt(s,old);success(currentProfile(s));switchProfile(s,'B');success(currentProfile(s),'english');s.profiles.A.learningLoop.runs[0].answers[0].correct=false;const original=structuredClone(s.profiles.A.wrongs);saveStore(storage,s);const raw=storage.getItem(STORE_KEY),loaded=loadStore(storage);assert.match(loaded.warning,/小步引导记录格式异常/);assert.deepEqual(loaded.store.profiles.A.wrongs,original);assert.equal(loaded.store.profiles.A.learningLoop,undefined);assert.deepEqual(loaded.store.profiles.B.learningLoop,s.profiles.B.learningLoop);assert.equal(storage.getItem(STORE_KEY),raw);});
test('invalid skip paths, unknown subjects, forged outcomes and malformed structure rejected',()=>{assert.equal(startLoop({},'constructor'),null);assert.equal(startLoop({},'math',{kind:'invented'}),null);for(const mutate of [s=>s.runs[0].answers[0]={...s.runs[0].answers[0],choice:'3',correct:false},s=>s.runs[0].answers[0].correct=false,s=>s.runs[0].phase='initial',s=>s.runs[0].id='loop-99',s=>s.runs[0].guides=[{choice:'x'}],s=>s.reviews.math.due='2026-02-30',s=>s.runs[0].selected='hack']){const p=currentProfile(createStore());success(p);mutate(p.learningLoop);assert.equal(validLoopState(p.learningLoop),false);}assert.equal(validLoopState(null),false);});
test('finite math assertions and bounded integer verifier reject non-integer, fractional and extreme requests',()=>{for(const q of loopBank.math.items){assert.equal(String(boundedDivision(q.total,q.groups)),q.answer);assert.equal(Number(q.answer)*q.groups,q.total);}for(const pair of [[0,3],[101,1],[12,0],[12,11],[10,3],[12.5,2],['12',3],[Infinity,2],[12,-3],[NaN,1]])assert.throws(()=>boundedDivision(...pair));});

test('stale A run actions cannot affect an already-populated B profile',()=>{const s=createStore(),a=currentProfile(s),ar=startLoop(a,'math',{at:time});switchProfile(s,'B');const b=currentProfile(s),br=startLoop(b,'math',{at:time});assert.notEqual(ar.id,br.id);assert.equal(loopAction(b,ar.id,ar.revision,'skip',null,time),false);assert.equal(br.phase,'initial');assert.equal(br.answers.length,0);});
test('review begun early and restored after its due day schedules from completion, not the start-day flag',()=>{const storage=mem(),s=createStore(),p=currentProfile(s);success(p);const r=startLoop(p,'math',{kind:'review',at:time});assert.equal(r.early,true);act(p,r,'select','3');saveStore(storage,s);const loaded=loadStore(storage);assert.equal(loaded.warning,'');const restored=currentProfile(loaded.store),rr=getLoop(restored,'math','review'),later=new Date(2026,10,15,12);act(restored,rr,'submit',null,later);assert.equal(rr.early,true);assert.equal(restored.learningLoop.reviews.math.due,'2026-11-18');assert.match(loopMarkup(rr),/开始时提前复习/);assert.doesNotMatch(loopMarkup(rr),/提前复习 · 不推迟原到期日/);assert.equal(validLoopState(restored.learningLoop),true);});
test('early review completed on the due date after help schedules next day',()=>{const p=currentProfile(createStore());success(p);const r=startLoop(p,'math',{kind:'review',at:time});answer(p,r,'6');guide(p,r);answer(p,r,'3',new Date(2026,10,14,12));assert.equal(p.learningLoop.reviews.math.due,'2026-11-15');assert.equal(validLoopState(p.learningLoop),true);});
test('persisted loop timestamps must be ISO strings, never null, coercible numbers or arrays',()=>{for(const value of [null,0,123,[],['2026-11-11'],{},'2026-11-11','invalid'])for(const path of ['startedAt','completedAt','answer','guide']){const p=currentProfile(createStore()),r=startLoop(p,'math',{at:time});answer(p,r,'3');guide(p,r);answer(p,r,'4');answer(p,r,'5');if(path==='answer')r.answers[0].at=value;else if(path==='guide')r.guides[0].at=value;else r[path]=value;assert.equal(validLoopState(p.learningLoop),false,`${path} ${JSON.stringify(value)}`);}});
